  if (isAwaitReading) {
    if (callbackId) {
      msg({
        callbackId,
        err: 'Worker is suspended waiting for file data (JSPI)',
      });
    }
    return;
  }

  if (!callbackId) {
    msg({ verb: 'console.error', args: ['callbackId is required', e.data] });
    return;
  }

